use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut stack = Vec::new();
    let mut current_value = String::new();

    for ch in input.as_str() {
        match ch {
            '{' => {
                stack.push(ch);
                current_value.push(ch);
            },
            '}' => {
                if stack.pop().is_none() {
                    return serde_json::Value::Null;
                }
                current_value.push(ch);
            },
            ',' => {
                if stack.pop().is_none() {
                    return serde_json::Value::Null;
                }
                current_value.push(ch);
            },
            '[' => {
                stack.push(ch);
                current_value.push(ch);
            },
            ']' => {
                if stack.pop().is_none() {
                    return serde_json::Value::Null;
                }
                current_value.push(ch);
            },
            '"' => {
                if stack.pop().is_none() {
                    return serde_json::Value::Null;
                }
                current_value.push(ch);
            },
            '0'..='9' => {
                current_value.push(ch);
            },
            _ => {
                return serde_json::Value::Null;
            }
        }
    }

    if stack.len() != 0 {
        return serde_json::Value::Null;
    }

    serde_json::Value::Bool(current_value.chars().all(|c| c.is_ascii_digit() || c == '[' || c == ']'))
}

fn main() {
    let input = serde_json::Value::from("{a{b[c](d)}");
    let expected = serde_json::Value::from(true);
    assert_eq!(solve(input), expected);
}
